CREATE OR REPLACE FUNCTION public.content_pipeline_dispatch_source_stage_v1(p_spec jsonb, p_pipeline_image_id bigint DEFAULT NULL::bigint, p_claim_token uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j uuid;t text;r bigint;i public."21_content_pipeline_image"%rowtype;h text;
begin
 if p_spec ? 'productionMethod' then raise exception 'USE_VISUAL_GENERATION_DISPATCH';end if;
 p_spec:=p_spec - array['rightsStatus','rights_status','rightsEvidence','licenseName','licenseUrl','permissionContact','permissionNote'];
 if jsonb_typeof(p_spec) is distinct from 'object' or length(p_spec::text)>16000 or p_spec->>'sourceAssetUrl' is null or jsonb_typeof(p_spec->'transform') is distinct from 'object' then raise exception 'INVALID_SOURCE_SPEC';end if;
 if (p_pipeline_image_id is null)<>(p_claim_token is null) then raise exception 'INVALID_IMAGE_CLAIM';end if;
 if p_pipeline_image_id is not null then
 select * into i from public."21_content_pipeline_image" where pipeline_image_id=p_pipeline_image_id;
 if not found or i.status<>'PROCESSING' or i.handoff_phase is distinct from 'PRODUCING' or i.claim_token is distinct from p_claim_token or i.claim_expires_at<=now() then raise exception 'INVALID_IMAGE_CLAIM';end if;
 if not exists(select 1 from public."18_content_pipeline" p where p.pipeline_id=i.pipeline_id and p.ownership_state='CLAIMED' and p.stage in('DRAFTED','VISUAL')) then raise exception 'INVALID_PIPELINE_STATE';end if;h:=i.generation_contract_hash;
 end if;
 t:=encode(extensions.gen_random_bytes(32),'hex');
 insert into public."27_content_pipeline_source_stage_job"(pipeline_image_id,claim_token,contract_hash,spec,token_hash) values(p_pipeline_image_id,p_claim_token,h,p_spec,extensions.digest(t,'sha256')) returning job_id into j;
 select net.http_post(url:='https://farjyjcvduthawpdjuqe.supabase.co/functions/v1/content-pipeline-source-stage',headers:=jsonb_build_object('content-type','application/json','x-fitbike-source-stage-ticket',t),body:=jsonb_build_object('jobId',j),timeout_milliseconds:=60000) into r;
 update public."27_content_pipeline_source_stage_job" set request_id=r where job_id=j;
 return jsonb_build_object('jobId',j,'requestId',r,'status','DISPATCHED','probeOnly',p_pipeline_image_id is null);
end $function$

CREATE OR REPLACE FUNCTION public.content_pipeline_visual_role_guard_v1(p_worker_key text, p_request_id uuid, p_action text, p_spec jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c jsonb;role text;i public."21_content_pipeline_image"%rowtype;j public."27_content_pipeline_source_stage_job"%rowtype;
begin
 c:=public.content_pipeline_visual_claim_request_status_v1(p_worker_key,p_request_id);
 if c->>'activeClaim' is distinct from 'true' then raise exception 'ACTIVE_VISUAL_CLAIM_REQUIRED';end if;
 role:=c->'claim'->>'executionRole';
 if role='PRODUCER' and p_action='DISPATCH' and (p_spec->>'preflightOnly' is distinct from 'true' or p_spec ? 'preStagingQa') then raise exception 'PRODUCER_PREFLIGHT_REQUIRED';end if;
 if role='PRODUCER' and p_action in ('QA','APPROVE') then raise exception 'REVIEWER_REQUEST_REQUIRED';end if;
 if role='REVIEWER' and p_action='QA' then
 select * into i from public."21_content_pipeline_image" where pipeline_image_id=(c->'claim'->>'pipelineImageId')::bigint;
 if p_spec->>'jobId' is distinct from i.review_candidate->>'jobId' or public.content_pipeline_review_candidate_v1(i.pipeline_image_id,(i.review_candidate->>'jobId')::uuid) is null then raise exception 'REVIEW_CANDIDATE_INVALID';end if;
 end if;
 if role='REVIEWER' and p_action='DISPATCH' then
  select * into i from public."21_content_pipeline_image" where pipeline_image_id=(c->'claim'->>'pipelineImageId')::bigint;
  select * into j from public."27_content_pipeline_source_stage_job" where job_id=(i.review_candidate->>'jobId')::uuid;
  if public.content_pipeline_review_candidate_v1(i.pipeline_image_id,j.job_id) is null or p_spec->>'preflightOnly'='true' then raise exception 'REVIEW_RESUME_REQUIRED';end if;
  if j.spec ? 'productionMethod' then
   if p_spec ? 'chatFile' or p_spec ? 'generatedAssetUrl' or p_spec ? 'inputFile' or p_spec->>'resumeJobId' is distinct from j.job_id::text
    or p_spec->>'prompt' is distinct from j.spec->>'prompt' or p_spec->'references' is distinct from j.spec->'references'
    or p_spec->>'productionMethod' is distinct from j.spec->>'productionMethod' or p_spec->>'inputAssetUrl' is distinct from j.spec->>'inputAssetUrl'
    then raise exception 'REVIEW_RESUME_REQUIRED';end if;
  elsif (p_spec-'preStagingQa'-'preflightOnly'-'transform') is distinct from (j.spec-'visualMcpOperation'-'preStagingQa'-'preflightOnly'-'transform') then raise exception 'REVIEW_SAME_SOURCE_REQUIRED';end if;
  if j.result->>'preflightOnly'='true' and (j.result->'preStagingQa'->>'status' is distinct from 'PASS' or p_spec->'preStagingQa' is distinct from j.result->'preStagingQa') then raise exception 'PRE_STAGING_VISUAL_QA_REQUIRED';end if;
 end if;
end $function$
